customCss:
/* Dracula for MarkText (custom) */
:root, body {
  --themeColor: #BD93F9; --highlightThemeColor: #FF79C6;
  --editorColor: #F8F8F2; --editorBgColor: #282A36;
  --editorColor80: rgba(248,248,242,.8); --editorColor60: rgba(248,248,242,.6);
  --editorColor50: rgba(248,248,242,.5); --editorColor40: rgba(248,248,242,.4);
  --editorColor30: rgba(248,248,242,.3); --editorColor10: rgba(248,248,242,.1);
  --editorColor04: rgba(248,248,242,.04);
  --selectionColor: #44475A; --codeBlockBgColor: #21222C; --codeBgColor: #21222C;
  --tableBorderColor: #44475A; --deleteColor: #FF5555; --iconColor: #6272A4;
  --sideBarBgColor: #21222C; --sideBarColor: #F8F8F2; --sideBarTitleColor: #BD93F9;
  --sideBarTextColor: #F8F8F2; --sideBarItemHoverBgColor: #44475A; --itemBgColor: #282A36;
  --floatBgColor: #21222C; --floatBorderColor: #44475A; --floatHoverColor: #44475A;
  --inputBgColor: #44475A; --buttonBgColor: #BD93F9;
}
#ag-editor-id h1, #ag-editor-id h2, #ag-editor-id h3,
#ag-editor-id h4, #ag-editor-id h5, #ag-editor-id h6 { color: #FF79C6 !important; }
#ag-editor-id a, #ag-editor-id .ag-inline-rule a { color: #8BE9FD !important; }
#ag-editor-id code, #ag-editor-id .ag-code-content { color: #50FA7B !important; }
#ag-editor-id strong { color: #FFB86C; }
#ag-editor-id em { color: #F1FA8C; }
#ag-editor-id blockquote { border-left-color: #BD93F9; color: #6272A4; }
#ag-editor-id li::marker { color: #FF79C6; }

/* Title bar (custom) — Dracula + JetBrainsMono */
body, .title-bar, .side-bar, .tabs-container, .el-dialog, .el-select-dropdown, .el-tooltip__popper {
  font-family: "JetBrainsMono Nerd Font", monospace !important;
}
.title-bar { background: #21222C !important; color: #F8F8F2 !important; border-bottom: 1px solid #44475A; }
.title-bar .title, .title-bar span { color: #F8F8F2 !important; }
.frameless-titlebar-button, .frameless-titlebar-menu { color: #BD93F9 !important; }
.frameless-titlebar-button svg, .frameless-titlebar-menu svg { fill: #BD93F9 !important; }
.frameless-titlebar-minimize:hover, .frameless-titlebar-toggle:hover, .frameless-titlebar-menu:hover { background: #44475A !important; }
.frameless-titlebar-close:hover { background: #FF5555 !important; }
.frameless-titlebar-close:hover svg { fill: #F8F8F2 !important; }

/* JetBrainsMono everywhere (UI + markdown text) */
.title-bar *, .side-bar *, .opened-files *, .project-tree *, .tree-view *, .side-bar-search *, .side-bar-toc *,
.tabs-container *, .el-dialog *, .el-select-dropdown *, .el-tooltip__popper, .el-message-box * {
  font-family: "JetBrainsMono Nerd Font", monospace !important;
}
#ag-editor-id, #ag-editor-id p, #ag-editor-id li, #ag-editor-id h1, #ag-editor-id h2, #ag-editor-id h3,
#ag-editor-id h4, #ag-editor-id h5, #ag-editor-id h6, #ag-editor-id td, #ag-editor-id th, #ag-editor-id blockquote {
  font-family: "JetBrainsMono Nerd Font", monospace !important;
}

/* SemiBold everywhere (JetBrainsMono 600); headings/bold stay 700 */
body, body *, .title-bar *, .side-bar *, .tabs-container *, .el-dialog *, .el-select-dropdown *,
#ag-editor-id, #ag-editor-id * {
  font-weight: 600;
}
#ag-editor-id h1, #ag-editor-id h2, #ag-editor-id h3, #ag-editor-id h4, #ag-editor-id h5, #ag-editor-id h6,
#ag-editor-id strong, #ag-editor-id b, #ag-editor-id th { font-weight: 800 !important; }
.katex, .katex * { font-weight: normal !important; }

/* Bold: also the spans inside <strong>/headings (the 600 rule on #ag-editor-id * was overriding them) */
#ag-editor-id strong, #ag-editor-id strong *, #ag-editor-id b, #ag-editor-id b *,
#ag-editor-id h1 *, #ag-editor-id h2 *, #ag-editor-id h3 *, #ag-editor-id h4 *, #ag-editor-id h5 *, #ag-editor-id h6 *,
#ag-editor-id th, #ag-editor-id th *, #ag-editor-id .ag-strong, #ag-editor-id .ag-strong * { font-weight: 800 !important; }
